Under Assumptions~\ref{assum:bounded-region},~\ref{assum:bounded-func-value}, and~\ref{assum:lipschitz-continuity}, for any $\delta>0$, $\eta >0$, and $\alpha = \delta/r$, the expected dynamic regret of \textsc{BGD}$(T, \delta,\alpha,\eta)$ for the one-point feedback model satisfies
\begin{equation}
  \label{eq:dynamic-regret-one-point}
  \E\left[\sum_{t=1}^T f_t(\x_t)\right] - \sum_{t=1}^T f_t(\u_t) \leq \frac{7R^2 + RP_T}{4\eta} + \frac{ \eta d^2 C^2T}{2\delta^2} + \big(3L + \frac{LR}{r}\big)\delta T,
\end{equation}
for \emph{any} feasible comparator sequence $\u_1,\ldots,\u_T \in \X$.

Under Assumptions~\ref{assum:bounded-region},~\ref{assum:bounded-func-value}, and~\ref{assum:lipschitz-continuity}, for any $\delta > 0$, $\eta>0$, and $\alpha = \delta/r$, the expected dynamic regret of \textsc{BGD}$(T, \delta,\alpha,\eta)$ for the two-point feedback model satisfies
\begin{equation}
  \label{eq:dynamic-regret-two-point}
  \E\left[\sum_{t=1}^T \frac{1}{2}\big(f_t(\x^{(1)}_t) + f_t(\x^{(2)}_t)\big)\right] - \sum_{t=1}^T f_t(\u_t) \leq \frac{7R^2 + RP_T}{4\eta} + \frac{\eta L^2 d^2}{2}T + \big(3L + \frac{LR}{r}\big)\delta T
\end{equation}

Under Assumptions~\ref{assum:bounded-region},~\ref{assum:bounded-func-value}, and~\ref{assum:lipschitz-continuity}, with a proper setting of the pool of candidate step sizes $\H$ and the learning rate $\epsilon$, \textsc{PBGD} algorithm enjoys the following expected dynamic regret,
\begin{compactitem}
  \item One-Point Feedback Model: $O\big(T^{\frac{3}{4}}(1+P_T)^{\frac{1}{2}}\big)$;
  \item Two-Point Feedback Model: $O\big(T^{\frac{1}{2}}(1+P_T)^{\frac{1}{2}}\big)$.
\end{compactitem}

For any $\tau \in [0, 2RT]$, there exists a comparator sequence $\u_1,\ldots,\u_T \in \X$ satisfying Assumption~\ref{assum:bounded-region} whose path-length $P_T$ is less than $\tau$, and a sequence of functions satisfying Assumption~\ref{assum:lipschitz-continuity}, such that for any algorithm designed for BCO with one-/two-point feedback who returns $\x_1,\ldots,\x_T$,
\begin{equation}
  \label{eq:lower-bound}
